package vn.vinhkhang.warehouse;
import java.util.*;import java.math.BigDecimal;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/deleted") public class DeletedRecords {
 final Api core;final JdbcTemplate db;final ObjectMapper json;public DeletedRecords(Api core,JdbcTemplate db,ObjectMapper json){this.core=core;this.db=db;this.json=json;}
 static final Map<String,String> TABLES=Map.of("parts","parts","stock","parts","suppliers","suppliers","models","vehicle_models","documents","stock_documents","bom","bom_versions","production","production_orders","receipts","vehicle_receipts","shipments","vehicle_shipments");
 static void capture(JdbcTemplate db,ObjectMapper json,String entity,long id,Object before){
  String key=entity.equals("stock")?"parts":entity;var snapshot=new LinkedHashMap<String,Object>();snapshot.put("record",before);
  if(Set.of("production","receipts").contains(key)){snapshot.put("vehicle_ids",db.queryForList("SELECT id FROM vehicles WHERE "+(key.equals("production")?"order_id":"receipt_id")+"=? AND deleted=FALSE ORDER BY id",Long.class,id));}
  if(Set.of("production","documents").contains(key)){var costs=new LinkedHashMap<String,Object>();String source=key.equals("production")?"production_id":"document_id";for(long part:db.queryForList("SELECT DISTINCT part_id FROM stock_movements WHERE "+source+"=?",Long.class,id))costs.put(Long.toString(part),Costing.sourceCost(db,part,key.equals("documents")?id:null,key.equals("production")?id:null));snapshot.put("costs",costs);}
  try{db.update("MERGE INTO deleted_records(entity,entity_id,snapshot,deleted_at) KEY(entity,entity_id) VALUES(?,?,?,CURRENT_TIMESTAMP)",key,id,json.writeValueAsString(snapshot));}catch(Exception e){throw new IllegalStateException("Không lưu được dữ liệu khôi phục",e);}
 }
 void access(String token,String entity){var s=core.admin(token);if(!TABLES.containsKey(entity))throw new Api.Problem(404,"Mục này không hỗ trợ khôi phục");if(Set.of("bom","production").contains(entity)&&AccountKinds.get(db,s.id()).equals("STORE"))throw new Api.Problem(403,"Chức năng không áp dụng cho tài khoản cửa hàng");}
 @GetMapping("/{entity}") public Object list(@RequestHeader("Authorization") String token,@PathVariable String entity){access(token,entity);String sql="SELECT * FROM "+TABLES.get(entity)+" WHERE deleted=TRUE ORDER BY id";return Set.of("parts","stock").contains(entity)?PartColors.catalog(db,sql):db.queryForList(sql);}
 @GetMapping("/{entity}/{id}/preview") @Transactional public Object preview(@RequestHeader("Authorization") String token,@PathVariable String entity,@PathVariable long id){access(token,entity);return restore(token,entity,id,false);}
 @PostMapping("/{entity}/{id}/restore") @Transactional public Object restore(@RequestHeader("Authorization") String token,@PathVariable String entity,@PathVariable long id,@RequestBody Map<String,Object> body){access(token,entity);core.str(body,"reason");return restore(token,entity,id,true);}
 @SuppressWarnings("unchecked") Object restore(String token,String entity,long id,boolean apply){
  String table=TABLES.get(entity),key=entity.equals("stock")?"parts":entity;var rows=db.queryForList("SELECT * FROM "+table+" WHERE id=? AND deleted=TRUE FOR UPDATE",id);if(rows.isEmpty())throw new Api.Problem(409,"Bản ghi đã được khôi phục hoặc không tồn tại");var row=rows.getFirst();Map<String,Object> saved=Map.of();var snapshots=db.queryForList("SELECT snapshot FROM deleted_records WHERE entity=? AND entity_id=?",key,id);if(!snapshots.isEmpty())try{saved=json.readValue(db.queryForObject("SELECT snapshot FROM deleted_records WHERE entity=? AND entity_id=?",String.class,key,id),Map.class);}catch(Exception e){throw new Api.Problem(409,"Không đọc được dữ liệu khôi phục");}
  var changes=new ArrayList<Map<String,Object>>();var vehicleIds=new ArrayList<Long>();var movements=new ArrayList<Map<String,Object>>();String note="Khôi phục thông tin; không thay đổi số lượng tồn kho.";String bomStatus="ACTIVE";
  Map<String,Object> costs=(Map<String,Object>)saved.getOrDefault("costs",Map.of());
  if(Set.of("parts","stock").contains(entity)){if(row.get("COLOR_PARENT_ID")!=null)core.active("parts",((Number)row.get("COLOR_PARENT_ID")).longValue());if(row.get("COLOR_MODEL_ID")!=null)core.active("vehicle_models",((Number)row.get("COLOR_MODEL_ID")).longValue());}
  if(entity.equals("bom")){core.active("vehicle_models",((Number)row.get("MODEL_ID")).longValue());for(long part:db.queryForList("SELECT part_id FROM bom_lines WHERE bom_id=?",Long.class,id))core.active("parts",part);var original=(Map<String,Object>)saved.get("record");if(original!=null)bomStatus=Objects.toString(original.get("STATUS"),"ACTIVE");else note="BOM cũ không có bản chụp: khôi phục ở trạng thái đang dùng, giữ nguyên định mức.";}
  if(entity.equals("documents")){ShipmentChargers.guard(db,id);
   if(row.get("SUPPLIER_ID")!=null)core.active("suppliers",((Number)row.get("SUPPLIER_ID")).longValue());SupplierReturns.validate(core,db,row,id);for(long part:db.queryForList("SELECT part_id FROM stock_document_lines WHERE document_id=?",Long.class,id))core.active("parts",part);
   if("POSTED".equals(row.get("STATUS"))){if(row.get("TYPE").equals("OUT")&&saved.isEmpty())costs=inverseCosts("documents",id,db.queryForList("SELECT part_id,quantity FROM stock_document_lines WHERE document_id=?",id));for(var line:db.queryForList("SELECT * FROM stock_document_lines WHERE document_id=? ORDER BY part_id",id)){long part=((Number)line.get("PART_ID")).longValue();core.active("parts",part);BigDecimal delta=((BigDecimal)line.get("QUANTITY")).multiply(BigDecimal.valueOf(row.get("TYPE").equals("IN")?1:-1));BigDecimal cost=row.get("TYPE").equals("IN")?(BigDecimal)line.get("UNIT_COST"):costs.containsKey(Long.toString(part))?Costing.cost(costs,Long.toString(part)):null;movements.add(movement(part,delta,cost));}note="Khôi phục phiếu đã ghi sổ và ghi lại đúng ảnh hưởng tồn kho bên dưới; không ghi đè các phiếu khác.";}
  }
  if(entity.equals("production")){
   for(var line:ProductionLines.detail(db,id)){core.active("bom_versions",((Number)line.get("BOM_ID")).longValue());core.active("vehicle_models",((Number)line.get("MODEL_ID")).longValue());}
   if(Boolean.TRUE.equals(row.get("MATERIALS_ISSUED"))){if(saved.isEmpty()){var legacy=db.queryForList("SELECT id FROM vehicles WHERE order_id=? AND deleted=TRUE AND status='AVAILABLE' AND receipt_id IS NULL ORDER BY id",Long.class,id);if(!row.get("STATUS").equals("COMPLETED")||legacy.size()!=((Number)row.get("QUANTITY")).intValue())throw new Api.Problem(409,"Lệnh cũ thiếu thông tin xe để khôi phục an toàn; giữ nguyên dữ liệu hiện tại");costs=inverseCosts("production",id,db.queryForList("SELECT part_id,quantity FROM production_materials WHERE order_id=?",id));vehicleIds.addAll(legacy);}for(var material:db.queryForList("SELECT * FROM production_materials WHERE order_id=? ORDER BY part_id",id)){long part=((Number)material.get("PART_ID")).longValue();core.active("parts",part);movements.add(movement(part,((BigDecimal)material.get("QUANTITY")).negate(),Costing.cost(costs,Long.toString(part))));}for(var v:(List<?>)saved.getOrDefault("vehicle_ids",List.of()))vehicleIds.add(((Number)v).longValue());note="Khôi phục lệnh, trừ lại linh kiện đã hoàn trả khi hủy và khôi phục các xe đã nhập trước lúc hủy. Các dữ liệu khác được giữ nguyên.";}
  }
  if(entity.equals("receipts")){
   vehicleIds.addAll(db.queryForList("SELECT id FROM vehicles WHERE receipt_id=? ORDER BY id",Long.class,id));if(row.get("PRODUCTION_ORDER_ID")!=null){long order=((Number)row.get("PRODUCTION_ORDER_ID")).longValue();var header=ProductionProgress.order(db,order);if(!Boolean.TRUE.equals(header.get("MATERIALS_ISSUED")))throw new Api.Problem(409,"Lệnh chưa phát hoặc đã hủy");var quantities=db.queryForList("SELECT production_line_id,COUNT(*) quantity FROM vehicles WHERE receipt_id=? GROUP BY production_line_id",id);for(var q:quantities){var line=db.queryForList("SELECT quantity,(SELECT COUNT(*) FROM vehicles WHERE production_line_id=? AND deleted=FALSE) received FROM production_order_lines WHERE id=?",q.get("PRODUCTION_LINE_ID"),q.get("PRODUCTION_LINE_ID")).getFirst();if(((Number)q.get("QUANTITY")).longValue()+((Number)line.get("RECEIVED")).longValue()>((Number)line.get("QUANTITY")).longValue())throw new Api.Problem(409,"Khôi phục sẽ vượt số xe của lệnh");}}note="Khôi phục xe của phiếu nhập vào kho; không trừ lại linh kiện của lệnh.";
  }
  if(entity.equals("shipments")){
   vehicleIds.addAll(db.queryForList("SELECT vehicle_id FROM vehicle_shipment_lines WHERE shipment_id=? ORDER BY vehicle_id",Long.class,id));for(long v:vehicleIds)if(db.queryForObject("SELECT COUNT(*) FROM vehicles WHERE id=? AND deleted=FALSE AND status='AVAILABLE'",Integer.class,v)!=1)throw new Api.Problem(409,"Xe #"+v+" đã xuất ở phiếu khác hoặc bị xóa; không khôi phục phiếu xuất này");for(var l:ShipmentChargers.lines(db,id)){long part=((Number)l.get("PART_ID")).longValue();core.active("parts",part);movements.add(movement(part,((BigDecimal)l.get("QUANTITY")).negate(),null));}note="Khôi phục phiếu xuất, xuất lại xe và sạc thực giao; giữ nguyên các phiếu khác.";
  }else for(long v:vehicleIds){var vehicle=db.queryForList("SELECT * FROM vehicles WHERE id=? AND deleted=TRUE AND status='AVAILABLE'",v);if(vehicle.isEmpty())throw new Api.Problem(409,"Xe #"+v+" không đủ điều kiện khôi phục");core.active("vehicle_models",((Number)vehicle.getFirst().get("MODEL_ID")).longValue());}
  if(entity.equals("shipments")&&"SALE".equals(row.get("SHIPMENT_PURPOSE"))||entity.equals("documents")&&"SALE".equals(row.get("SALES_PURPOSE")))note+=" Doanh số và các khoản thu/chi đã xóa không được tự khôi phục; anh bổ sung riêng trong báo cáo nếu cần.";
  for(var move:movements){long part=((Number)move.get("part")).longValue();BigDecimal delta=(BigDecimal)move.get("delta");var balance=db.queryForList("SELECT quantity FROM stock_balances WHERE part_id=? AND location_id=1 FOR UPDATE",part);BigDecimal before=balance.isEmpty()?BigDecimal.ZERO:(BigDecimal)balance.getFirst().get("QUANTITY");if(before.add(delta).signum()<0)throw new Api.Problem(409,"Không đủ tồn để khôi phục: "+db.queryForObject("SELECT name FROM parts WHERE id=?",String.class,part));var item=new LinkedHashMap<String,Object>();item.put("code",PartColors.displayCode(db,part));item.put("name",db.queryForObject("SELECT name FROM parts WHERE id=?",String.class,part));item.put("before",before);item.put("change",delta);item.put("after",before.add(delta));changes.add(item);}
  if(apply){
   if(entity.equals("shipments"))ShipmentChargers.restore(core,db,id);
   for(var move:entity.equals("shipments")?List.<Map<String,Object>>of():movements)Costing.move(core,db,((Number)move.get("part")).longValue(),(BigDecimal)move.get("delta"),entity.equals("documents")?id:null,entity.equals("production")?id:null,(BigDecimal)move.get("cost"),true);
   db.update("UPDATE "+table+" SET deleted=FALSE WHERE id=?",id);if(entity.equals("bom"))db.update("UPDATE bom_versions SET status=? WHERE id=?",bomStatus,id);
   if(entity.equals("shipments"))for(long v:vehicleIds)db.update("UPDATE vehicles SET status='SHIPPED' WHERE id=?",v);else for(long v:vehicleIds)db.update("UPDATE vehicles SET deleted=FALSE WHERE id=?",v);
   if(entity.equals("production")){for(long receipt:db.queryForList("SELECT DISTINCT receipt_id FROM vehicles WHERE order_id=? AND deleted=FALSE AND receipt_id IS NOT NULL",Long.class,id))db.update("UPDATE vehicle_receipts SET deleted=FALSE WHERE id=?",receipt);ProductionProgress.refresh(db,id);}
   if(entity.equals("receipts")&&row.get("PRODUCTION_ORDER_ID")!=null)ProductionProgress.refresh(db,((Number)row.get("PRODUCTION_ORDER_ID")).longValue());core.audit(core.admin(token),"RESTORE",entity,id);
  }
  return Map.of("note",note,"stock_changes",changes,"vehicle_change",vehicleIds.size()*(entity.equals("shipments")?-1:1),"restored",apply);
 }
 Map<String,Object> inverseCosts(String entity,long id,List<Map<String,Object>> lines){var rates=new LinkedHashMap<String,Object>();String column=entity.equals("production")?"production_id":"document_id";for(var line:lines){long part=((Number)line.get("PART_ID")).longValue();var rows=db.queryForList("SELECT quantity,unit_cost FROM stock_movements WHERE "+column+"=? AND part_id=? ORDER BY id DESC FETCH FIRST 1 ROW ONLY",id,part);BigDecimal net=db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE "+column+"=? AND part_id=?",BigDecimal.class,id,part);if(rows.isEmpty()||net.signum()!=0||((BigDecimal)rows.getFirst().get("QUANTITY")).compareTo((BigDecimal)line.get("QUANTITY"))!=0)throw new Api.Problem(409,"Giao dịch cũ thiếu lịch sử hoàn tồn chính xác; không khôi phục để tránh đổi sai kho");rates.put(Long.toString(part),rows.getFirst().get("UNIT_COST"));}return rates;}
 static Map<String,Object> movement(long part,BigDecimal delta,BigDecimal cost){var m=new LinkedHashMap<String,Object>();m.put("part",part);m.put("delta",delta);m.put("cost",cost);return m;}
}
